,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-card.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Pick a Style, then map Title (required) and any of Eyebrow, Description, Details, Icon, Image URL, Badge, State, Value, Value Label, Meta, Link URL and Link Label. Empty settings are left out. With Link URL the whole card is clickable. Pointer effects (Spotlight, Tilt 3D, Holo Foil) need the plug-in JavaScript file and run only with a mouse or pen; every effect also runs on keyboard focus, and all motion stops when the user asks the system for reduced motion.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(708722888048376999)
,p_plugin_id=>wwv_flow_imp.id(273917889919212700)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'borderBeam'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Card design, grouped by direction. MOTION - Border Beam: a light travels around the border. Spotlight: a glow follows the pointer and lights the border of neighbouring cards. Meteors: diagonal light streaks across a night-tinted card. DEPTH - Tilt 3D: the card tilts toward the pointer while its layers float at different depths under a glare. Flip: summary on the front, Details on the back, turned on hover, focus or tap. Layered Stack: two tinted sheets behind the card fan out on hover. BOLD - Neo Brutal: ink border, hard offset shadow, flat fills. Clay: pillowy soft-shadow surface. Aurora Grain: slow aurora gradient under film grain. Holo Foil: holographic foil that shifts with the pointer. SMART - Expand Reveal: a compact card that morphs open to show Description, Details and the action on hover, focus or tap. Adaptive: container queries switch between stacked, side-by-side and billboard compositions; in report mode the first card spans the full row as a billboard.'
);
